    '1aa36213cb676fd5baad5edc2bee4fbe117a778b' => ['name' => 'Raziskovalci (aliansa)', 'description' => '+10% hitrosti do destinacije ekspedicij<br />+5% večji planeti pri kolonizaciji<br />Dostop do falange sistema: za 40,000 deuteriuma se lahko to uporabi za pregled gibanja flot v celotnih sistemih, dokler so ti v dometu.', 'duration_label' => 'za 40,000 deuteriuma se lahko to uporabi za pregled gibanja flot v celotnih sistemih, dokler so ti v dometu.', 'extended_description' => 'Največja odkritja se zgodijo, ko dela skupaj veliko mislecev. Aliansa raziskovalcev ne le odkriva večjih planetov za kolonizacijo, ampak ima tudi hitrejše ladje na ekspedicijah. Skupaj imajo dostop do falango sistema, ki se lahko uporabi za pregled gibanja flot v vseh sistemih.'],
    '6c9fe5e35bdad0d4e3382eb6a5aeac6bc8263752' => ['name' => 'Trgovci (aliansa)', 'description' => '+10% hitrosti za transporterje<br />+5% proizvodnje za surovine in energijo<br />+10% kapacitete skladišč na lunah in planetih', 'duration_label' => 'Stalen', 'extended_description' => 'Trgovalne alianse nagrajujejo vse vpletene sodelujoče in nihče ne ve tega bolje od alianse trgovcev. Njihovi transporterji letijo hitreje in postopki proizvodnje energije in surovin so optmizirani, da lahko bolje zaslužijo. Z izboljšano logistiko imajo več prostora za skladiščenje na planetih in lunah.'],
    '9b48e257cbef6c5df0f03a47cead7f9abda3d437' => ['name' => 'Bojevniki (aliansa)', 'description' => '+10% hitrosti za ladje, ki letijo med člani alianse<br />+1 stopnja raziskav za bitke<br />+1 stopnja raziskav vohunjenja<br />Dostop do vohunjenja sistema: pošlje izbrano število vohunskih sond v pregled celotnega sistema. Za raziskavo lahko nastaviš tip nebesnega telesa, čas od zadnjega vohunskega napada ali željeno aktivnost igralca.', 'duration_label' => 'pošlje izbrano število vohunskih sond v pregled celotnega sistema. Za raziskavo lahko nastaviš tip nebesnega telesa, čas od zadnjega vohunskega napada ali željeno aktivnost igralca.', 'extended_description' => 'Včasih morajo tudi najmočnejši bojevniki skleniti pakt, da lahko skupaj vladajo galaksiji. Tehnologija vohunjenja, ki je na voljo takšni zvezi, omogoča lažjo identifikacijo primernih tarč za napade. Njihova tehnologija je tako močnejša in pripravljeni so na vse.'],
    'dc34fa00ba914ffab0031ac3f165e26f553d7809' => ['name' => 'Avatar: Laserska mačka', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Mačke in laserji so neločljiva kombinacija - zdaj lahko opremiš svoj profil z najboljšim od obojnega!'],
    '1c497ef926d674f2df9d96cfc58fe12f97cf4025' => ['name' => 'Avatar: Majhni vesoljček', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'V širjavah vesolja nenehno odkrivajo nove oblike inteligentnega življenja. Veliko je popolnoma drugačnih od ljudi in imajo svoje prednosti in slabosti.'],
    'fd3b0789b5dca99e9d5b251f8bae0760ce52dea6' => ['name' => 'Avatar: Povečan', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Znanost je že davno presegla meje krhkega človeškega telesa. Vsadki in drugi tehnološki napredki ti omogočajo, da si hitrejši, trdnejši in močnejši od ostalih.'],
    '003db2a3d693c2d889864b76ad122b274bfd641b' => ['name' => 'Avatar: Breztežnostni', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Prvi sprehod v vesolju je velik mejnik v karieri vsakega mladega astronavta, ne glede na vrsto. Občutek lebdenja med zvezdami in pogled na droben domači planet bosta ostala v tebi do konca tvojih dni.'],
    '8d514b69eb04a57495bab0c8f4b80f58294a7b17' => ['name' => 'Avatar: Ledeno hladen', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Ledeni planeti so cenjeni zaradi bogatih depozitov Deuteriuma, a včasih je lahko potrebno povečati njihovo obrambo. Kdo ve, kaj preži med ledom in snegom...'],
    '83c4e79697a264462e3ca2e8567307e7f1d7954b' => ['name' => 'Avatar: Kiberprostor', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Mnogo novincev, ki upajo, da si bodo zaslužili srečo med zvezdami, razvijejo svoj stil v času svoje kariere. Ta jim pomaga pridobiti ugled in povečati njihovo mesto v sumljivih krogih.'],
    '2d7de180f3f3d191982294d2f8c1cd7507e90cb4' => ['name' => 'Avatar: Retro mucki', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Legenda govori o očarljivi mucki, ki za seboj pušča mavrico, ko leti skozi neslutene širjave vesolja. Nekateri dvomljivci so skušati ovreči mite, da je bila to težava pri sistemu filtracije pilotske kabine, a kdo ve...'],
    'c54d5a8f36f20373c5bb633a109241290b2e2a7a' => ['name' => 'Avatar: Prinašalec vojne', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Tisti, ki vladajo z železno roko, so pogosto smatrani kot nevarna osebnost. Ljudje, ki se pritožujejo ali jih častijo, morajo takoj prepoznati, s kom imajo opravka.'],
    '99f53568108115acac2d7f7425ee2ad76a6206b8' => ['name' => 'Avatar: Komandantka Kitty', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Hitri refleksi so prednost vsakega vesoljskega vladarja, saj prisrčen izgled pogosto zavede premetene misli med koničastimi ušesi.'],
    'c70f11e9543100622e3ef3bdcd57099a63f148bf' => ['name' => 'Avatar: Usoda', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Myriad so konflikti, ki v prostranem vesolju živijo od odprtja D20. Stranice te kocke so prazne - kakšna bo odločitev?'],
    'ac5bd99552a23733f7b0decac45094d5bfbfedac' => ['name' => 'Avatar: Goreč bes', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Nekateri vladarji med zvezdami sejejo strah med ljudmi, ko so opažene njihove flote. Le norec bi spodbujal njihovo jezo.'],
    'da8b1dcf6a9defb45e456968d3c8587bf63a48b5' => ['name' => 'Omejeni avatar: Horizont eventa', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Kot se je izkazalo, pregovor starega raziskovalca o drznem stopanju čez mejo pride do omejitev, ko govorimo o potovanjih po vesolju...'],
    '69719df021ec40424225f22e2edca15b799401a5' => ['name' => 'Omejeni avatar: Zvezdni pilot', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Najbolj talentirani in najbolj ostri piloti ter največji umi nosijo dediščino človeštva daleč k zvezdam.'],
    'facb9419f24c4a1fbff7dc29376c3f57c6204c1c' => ['name' => 'Omejeni avatar: Android', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Popolnoma mehanske ekipe so lahko zelo napredne v sovražnih okoljih. Zahtevajo tudi manj tovornega prostora za obroke, medtem ko tehnologija hitrega polnjena pomeni, da je polnjenje na polnilnicah krajše od klasičnega spanja. Zaradi naprednih baterijskih sistemov pa niso pritrjeni s polnilnimi kabli, niti na ledenih planetih.'],
    '74bf9741209dc8ef4f9996b8b2b7ca59001ea3a8' => ['name' => 'Omejeni avatar: Zvezdna želva', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Obstoj zvezdnih želv je kontroverzna tema med strokovnjaki, a govorice še trmasto vztrajajo. Poročila o videnjih jih redno povezujejo z debelokožci, ploščatimi nebesnimi telesi in drugimi drugačnostmi...'],
    '07a4b64949fcc593435cfaa9184290af96ffdc29' => ['name' => 'Omejeni avatar: Nakovalo usode', 'description' => 'Za dodajanje tega avatarja, ga izberi v svojem profilu igralca in daj svojemu profilu osebni slog. Ta predmet bo odklenjen za tvoj račun v vseh vesoljih. Pazi, saj lahko sinhronizacija med vesolji traja nekaj časa.', 'duration_label' => 'Stalen', 'extended_description' => 'Vsak vladar drži usodo svojega galaktičnega imperija v svojih rokah. To usodo si krojiš sam, saj tvoj talent in možnost predvidevanja odloča med zmago in porazom.'],
